from moler.exceptions import ParsingDone
from moler.cmd.unix.genericunix import GenericUnixCommand
import re


class L2uDtb(GenericUnixCommand):
    """Command l2u_dtb."""

    def __init__(self, connection, mode, number, start_over=False, prompt=None, newline_chars=None, runner=None):
        """
        Command l2u_dtb.

        :param connection: moler connection to device, terminal when command is executed
        :param start_over: start over flag
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(L2uDtb, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                     runner=runner)
        self.mode = mode
        self.number = number
        self.start_over = start_over
        self._is_started_over = False
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "l2u-dtb"
        cmd = f"{cmd} {self.mode}"
        cmd = f"{cmd} {self.number}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        try:
            self._asks_to_start_over(line)
            if is_full_line:
                self._parse_info(line)
        except ParsingDone:
            pass
        return super(L2uDtb, self).on_new_line(line, is_full_line)

    # Do you want to clear it, and start over? [y/n]
    _re_start_over = re.compile(r"Do\syou\swant\sto\sclear\sit,\sand\sstart\sover\?\s\[y/n\]")

    def _asks_to_start_over(self, line):
        if self._regex_helper.search_compiled(L2uDtb._re_start_over, line) and not self._is_started_over:
            self._is_started_over = True
            if self.start_over:
                self.connection.sendline('y')
            else:
                self.connection.sendline('n')
            raise ParsingDone

    # [L2U INFO] Challenge code: 0b033402d3c5e458acc391e025276d8773a3260cb828dcf54d4417be506ddc0a
    _re_info = re.compile(r"^(\[L2U INFO\])?\s+(?P<NAME>.*):\s+(?P<VALUE>.*)")

    def _parse_info(self, line):
        if self._regex_helper.search_compiled(L2uDtb._re_info, line):
            self.current_ret[self._regex_helper.group('NAME')] = self._regex_helper.group('VALUE')
            raise ParsingDone


